const value = '14/02/2020';
function convertDmyDate(value) {
  if (typeof value !== 'string' || value.length !== 10) throw new Error('Enter a date in DD/MM/YYYY format');
  const match = /^([0-9]{2})\/([0-9]{2})\/([0-9]{4})$/.exec(value);
  if (!match) throw new Error('Enter a date in DD/MM/YYYY format');
  const [, dayText, monthText, yearText] = match;
  const day = Number(dayText), month = Number(monthText), year = Number(yearText);
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const monthDays = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (month < 1 || month > 12 || day < 1 || day > monthDays[month - 1]) throw new Error('Enter a valid calendar date');
  return monthText + '/' + dayText + '/' + yearText;
}
async function dmyDate({ value }) {
  return { data: convertDmyDate(value) };
}

return { json: { data: convertDmyDate(value) } };
